import { Router, Request, Response } from 'express';
import { db } from '../../db';
import { requireAuth } from '../../auth/middleware';

export const orderRouter = Router();

// GET /api/v1/orders/:id  -> untyped JSON, legacy field names
orderRouter.get('/:id', requireAuth, async (req: Request, res: Response) => {
  const row = await db.orders.findById(req.params.id);
  if (!row) return res.status(404).json({ error: 'order not found' });
  res.json({
    id: row.id,
    status: row.status,
    total_cents: row.totalCents,
    created: row.createdAt,
    customer_id: row.customerId,
  });
});

// GET /api/v1/orders?customer=...
orderRouter.get('/', requireAuth, async (req: Request, res: Response) => {
  const rows = await db.orders.list({ customerId: String(req.query.customer ?? '') });
  res.json(rows.map((r) => ({ id: r.id, status: r.status, total_cents: r.totalCents })));
});

// POST /api/v1/orders
orderRouter.post('/', requireAuth, async (req: Request, res: Response) => {
  const created = await db.orders.create(req.body);
  res.status(201).json({ id: created.id });
});

