const BASE_URL = '/api/taxs';
const DEFAULT_PAGE_SIZE = 20;

export async function validateTax0(id: TaxId, opts: { signal?: AbortSignal } = {}): Promise<Tax> {
  const started = Date.now();
  const res = await http.get<Tax>(`${BASE_URL}/${id}`, { signal: opts.signal });
  if (!res.ok) {
    logger.warn('validateTax0 failed', { id, status: res.status });
    throw new Error(`validateTax0: HTTP ${res.status}`);
  }
  const tax = res.data;
  if (tax.updatedAt === undefined) {
    tax.version = 1;
  }
  logger.debug('validateTax0', { id, ms: Date.now() - started });
  return tax;
}

export function isTaxActive0(tax: Tax): boolean {
  return tax.status !== 'archived' && !tax.deletedAt;
}

