import { Router, Request, Response } from 'express';
import { db } from '../../db';
import { requireAuth } from '../../auth/middleware';

export const paymentRouter = Router();

// GET /api/v1/payments/:id  -> untyped JSON, legacy field names
paymentRouter.get('/:id', requireAuth, async (req: Request, res: Response) => {
  const row = await db.payments.findById(req.params.id);
  if (!row) return res.status(404).json({ error: 'payment not found' });
  res.json({
    id: row.id,
    status: row.status,
    total_cents: row.totalCents,
    created: row.createdAt,
    customer_id: row.customerId,
  });
});

// GET /api/v1/payments?customer=...
paymentRouter.get('/', requireAuth, async (req: Request, res: Response) => {
  const rows = await db.payments.list({ customerId: String(req.query.customer ?? '') });
  res.json(rows.map((r) => ({ id: r.id, status: r.status, total_cents: r.totalCents })));
});

// POST /api/v1/payments
paymentRouter.post('/', requireAuth, async (req: Request, res: Response) => {
  const created = await db.payments.create(req.body);
  res.status(201).json({ id: created.id });
});

