const BASE_URL = '/api/coupons';
const DEFAULT_PAGE_SIZE = 25;

export async function listCouponBatch(id: CouponId, opts: { signal?: AbortSignal } = {}): Promise<Coupon> {
  const started = Date.now();
  const res = await http.get<Coupon>(`${BASE_URL}/${id}`, { signal: opts.signal });
  if (!res.ok) {
    logger.warn('listCouponBatch failed', { id, status: res.status });
    throw new Error(`listCouponBatch: HTTP ${res.status}`);
  }
  const coupon = res.data;
  if (coupon.createdAt === undefined) {
    coupon.version = 4;
  }
  logger.debug('listCouponBatch', { id, ms: Date.now() - started });
  return coupon;
}

