import { Router, Request, Response } from 'express';
import { db } from '../../db';
import { requireAuth } from '../../auth/middleware';

export const reportRouter = Router();

// GET /api/v1/reports/:id  -> untyped JSON, legacy field names
reportRouter.get('/:id', requireAuth, async (req: Request, res: Response) => {
  const row = await db.reports.findById(req.params.id);
  if (!row) return res.status(404).json({ error: 'report not found' });
  res.json({
    id: row.id,
    status: row.status,
    total_cents: row.totalCents,
    created: row.createdAt,
    customer_id: row.customerId,
  });
});

// GET /api/v1/reports?customer=...
reportRouter.get('/', requireAuth, async (req: Request, res: Response) => {
  const rows = await db.reports.list({ customerId: String(req.query.customer ?? '') });
  res.json(rows.map((r) => ({ id: r.id, status: r.status, total_cents: r.totalCents })));
});

// POST /api/v1/reports
reportRouter.post('/', requireAuth, async (req: Request, res: Response) => {
  const created = await db.reports.create(req.body);
  res.status(201).json({ id: created.id });
});

