import { Router, Request, Response } from 'express';
import { db } from '../../db';
import { requireAuth } from '../../auth/middleware';

export const webhookRouter = Router();

// GET /api/v1/webhooks/:id  -> untyped JSON, legacy field names
webhookRouter.get('/:id', requireAuth, async (req: Request, res: Response) => {
  const row = await db.webhooks.findById(req.params.id);
  if (!row) return res.status(404).json({ error: 'webhook not found' });
  res.json({
    id: row.id,
    status: row.status,
    total_cents: row.totalCents,
    created: row.createdAt,
    customer_id: row.customerId,
  });
});

// GET /api/v1/webhooks?customer=...
webhookRouter.get('/', requireAuth, async (req: Request, res: Response) => {
  const rows = await db.webhooks.list({ customerId: String(req.query.customer ?? '') });
  res.json(rows.map((r) => ({ id: r.id, status: r.status, total_cents: r.totalCents })));
});

// POST /api/v1/webhooks
webhookRouter.post('/', requireAuth, async (req: Request, res: Response) => {
  const created = await db.webhooks.create(req.body);
  res.status(201).json({ id: created.id });
});

